export type TextDeltaHandler = (delta: string) => void;

export function responseOutputText(response: any): string {
  if (typeof response?.output_text === "string" && response.output_text.trim()) return response.output_text.trim();
  const output = Array.isArray(response?.output) ? response.output : [];
  return output
    .filter((item: any) => item?.type === "message" && Array.isArray(item.content))
    .flatMap((item: any) => item.content)
    .filter((part: any) => part?.type === "output_text" || part?.type === "text")
    .map((part: any) => typeof part.text === "string" ? part.text : "")
    .join("\n")
    .trim();
}

export function shouldContinueResponse(response: any, continuationCount: number, maxContinuations = 2): boolean {
  return response?.status === "incomplete" &&
    response?.incomplete_details?.reason === "max_output_tokens" &&
    continuationCount < maxContinuations;
}

/** Consume OpenRouter Responses API SSE, exposing only user-visible text deltas. */
export async function readResponsesStream(
  body: ReadableStream<Uint8Array>,
  onTextDelta?: TextDeltaHandler,
): Promise<any> {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let finalResponse: any = null;
  let streamError: Error | null = null;

  const consumeLine = (raw: string) => {
    const line = raw.endsWith("\r") ? raw.slice(0, -1) : raw;
    if (!line.startsWith("data:")) return;
    const payload = line.slice(5).trim();
    if (!payload || payload === "[DONE]") return;
    let event: any;
    try { event = JSON.parse(payload); } catch { return; }
    if (event?.type === "response.output_text.delta" && typeof event.delta === "string") {
      if (event.delta) onTextDelta?.(event.delta);
      return;
    }
    if (event?.type === "response.completed" || event?.type === "response.incomplete") {
      finalResponse = event.response || null;
      return;
    }
    if (event?.type === "response.failed" || event?.type === "error") {
      streamError = new Error("Model provider reported a streamed response error");
    }
  };

  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      let newline = -1;
      while ((newline = buffer.indexOf("\n")) !== -1) {
        const line = buffer.slice(0, newline);
        buffer = buffer.slice(newline + 1);
        consumeLine(line);
        if (streamError) throw streamError;
      }
    }
    buffer += decoder.decode();
    if (buffer.trim()) consumeLine(buffer);
    if (streamError) throw streamError;
    if (!finalResponse) throw new Error("Model stream ended without a terminal response event");
    return finalResponse;
  } finally {
    reader.releaseLock();
  }
}


export function responsesInputToChatMessages(input: unknown, instructions?: string): any[] {
  const messages: any[] = [];
  if (typeof instructions === "string" && instructions.trim()) messages.push({ role: "system", content: instructions });
  let pendingAssistantText = "";
  let pendingToolCalls: any[] = [];
  const flushAssistant = () => {
    if (!pendingAssistantText && !pendingToolCalls.length) return;
    messages.push({
      role: "assistant",
      content: pendingAssistantText || null,
      ...(pendingToolCalls.length ? { tool_calls: pendingToolCalls } : {}),
    });
    pendingAssistantText = "";
    pendingToolCalls = [];
  };
  for (const item of Array.isArray(input) ? input : []) {
    if (!item || typeof item !== "object") continue;
    const value = item as any;
    if (value.type === "function_call") {
      const id = String(value.call_id || value.id || "");
      const name = String(value.name || "");
      const args = String(value.arguments || "{}");
      if (!id || !name) throw new Error("Gemini tool-call history is missing its call ID or function name");
      let parsed: unknown;
      try { parsed = JSON.parse(args); } catch { throw new Error("Gemini tool-call history contains invalid arguments"); }
      if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) throw new Error("Gemini tool-call arguments must be a JSON object");
      pendingToolCalls.push({ id, type: "function", function: { name, arguments: args } });
      continue;
    }
    if (value.type === "message" && value.role === "assistant") {
      const text = Array.isArray(value.content)
        ? value.content.map((part: any) => typeof part?.text === "string" ? part.text : "").join("")
        : "";
      pendingAssistantText += text;
      continue;
    }
    if (value.role === "assistant") {
      pendingAssistantText += typeof value.content === "string" ? value.content : JSON.stringify(value.content ?? "");
      continue;
    }
    flushAssistant();
    if (value.type === "function_call_output") {
      const callId = String(value.call_id || "");
      if (!callId) throw new Error("Gemini tool output is missing its call ID");
      messages.push({ role: "tool", tool_call_id: callId, content: typeof value.output === "string" ? value.output : JSON.stringify(value.output ?? "") });
      continue;
    }
    if (value.role === "user" || value.role === "system") {
      const content = typeof value.content === "string" ? value.content : JSON.stringify(value.content ?? "");
      messages.push({ role: value.role, content });
    }
  }
  flushAssistant();
  return messages;
}

export function responsesToolsToChatTools(tools: unknown): any[] {
  return (Array.isArray(tools) ? tools : []).filter((tool: any) => tool?.type === "function").map((tool: any) => ({
    type: "function",
    function: {
      name: String(tool.name || ""),
      description: String(tool.description || ""),
      parameters: tool.parameters && typeof tool.parameters === "object" ? tool.parameters : { type: "object", properties: {} },
    },
  }));
}

/** Read Google Gemini's OpenAI-compatible Chat Completions SSE and normalise it to the Responses shape JD already consumes. */
export async function readChatCompletionsStream(body: ReadableStream<Uint8Array>, onTextDelta?: TextDeltaHandler): Promise<any> {
  const reader = body.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  let content = "";
  let finishReason: string | null = null;
  let responseId: string | null = null;
  let model: string | null = null;
  const toolCalls = new Map<number, any>();
  let usage: any = undefined;
  const consumeLine = (raw: string) => {
    const line = raw.endsWith("\r") ? raw.slice(0, -1) : raw;
    if (!line.startsWith("data:")) return;
    const payload = line.slice(5).trim();
    if (!payload || payload === "[DONE]") return;
    let chunk: any;
    try { chunk = JSON.parse(payload); } catch { throw new Error("Gemini returned a malformed streaming event"); }
    if (chunk.error) throw new Error("Gemini streamed response failed");
    responseId ||= chunk.id || null;
    model ||= chunk.model || null;
    if (chunk.usage) usage = chunk.usage;
    const choice = chunk.choices?.[0];
    if (!choice) return;
    if (choice.finish_reason) finishReason = choice.finish_reason;
    const delta = choice.delta || {};
    if (typeof delta.content === "string" && delta.content) {
      content += delta.content;
      onTextDelta?.(delta.content);
    }
    for (const part of delta.tool_calls || []) {
      const index = Number(part.index);
      if (!Number.isInteger(index) || index < 0) throw new Error("Gemini returned an invalid tool-call index");
      const current = toolCalls.get(index) || { id: "", type: "function", function: { name: "", arguments: "" } };
      if (part.id) current.id = part.id;
      if (part.function?.name) current.function.name += part.function.name;
      if (part.function?.arguments) current.function.arguments += part.function.arguments;
      toolCalls.set(index, current);
    }
  };
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      let newline;
      while ((newline = buffer.indexOf("\n")) !== -1) {
        const line = buffer.slice(0, newline);
        buffer = buffer.slice(newline + 1);
        consumeLine(line);
      }
    }
    buffer += decoder.decode();
    if (buffer.trim()) consumeLine(buffer);
    if (!finishReason) throw new Error("Gemini stream ended without a terminal completion marker");
    if (!["stop", "tool_calls", "length"].includes(finishReason)) throw new Error("Gemini ended with an unsupported finish reason");
    const calls = [...toolCalls.entries()].sort(([a], [b]) => a - b).map(([, call]) => {
      if (finishReason === "length") return call;
      if (!call.id || !call.function.name || !call.function.arguments) throw new Error("Gemini returned an incomplete tool call");
      let args: unknown;
      try { args = JSON.parse(call.function.arguments); } catch { throw new Error("Gemini returned invalid tool-call arguments"); }
      if (!args || typeof args !== "object" || Array.isArray(args)) throw new Error("Gemini tool-call arguments must be a JSON object");
      return call;
    });
    if (!content && !calls.length && finishReason !== "length") throw new Error("Gemini stream ended without a readable response or tool call");
    if (finishReason === "tool_calls" && !calls.length) throw new Error("Gemini reported tool calls but returned none");
    const output: any[] = [];
    if (content) output.push({ type: "message", role: "assistant", content: [{ type: "output_text", text: content }] });
    for (const call of calls) output.push({
      type: "function_call",
      call_id: call.id,
      name: call.function.name,
      arguments: call.function.arguments,
    });
    const status = finishReason === "length" ? "incomplete" : "completed";
    return {
      id: responseId,
      model,
      status,
      ...(status === "incomplete" ? { incomplete_details: { reason: "max_output_tokens" } } : {}),
      output,
      output_text: content,
      usage: usage ? {
        input_tokens: usage.prompt_tokens || 0,
        output_tokens: usage.completion_tokens || 0,
        total_tokens: usage.total_tokens || 0,
      } : undefined,
    };
  } finally {
    reader.releaseLock();
  }
}

export type JdDocumentFormat = "txt" | "md" | "csv" | "json" | "html" | "css" | "js" | "ts" | "py" | "sql" | "xml" | "yaml" | "docx" | "xlsx" | "pptx";

export const JD_DOCUMENT_MIME: Record<JdDocumentFormat, string> = {
  txt: "text/plain",
  md: "text/markdown",
  csv: "text/csv",
  json: "application/json",
  html: "text/html",
  css: "text/css",
  js: "text/javascript",
  ts: "text/plain",
  py: "text/x-python",
  sql: "application/sql",
  xml: "application/xml",
  yaml: "text/yaml",
  docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  xlsx: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  pptx: "application/vnd.openxmlformats-officedocument.presentationml.presentation",
};

export function sanitizeGeneratedFilename(value: unknown, format: JdDocumentFormat): string {
  const raw = typeof value === "string" ? value.trim().replace(/\\/g, "/") : "";
  if (!raw || raw.startsWith("/") || raw.length > 160) throw new Error("A relative filename of at most 160 characters is required");
  const segments = raw.split("/");
  if (segments.some((part) => !part || part === "." || part === "..")) throw new Error("Filename path traversal is not allowed");
  const clean = segments.map((part) => part.replace(/[^a-z0-9._-]/gi, "-")).join("/");
  const extension = format;
  const leaf = clean.split("/").pop() || "";
  const safeLeaf = leaf.toLowerCase().endsWith("." + extension) ? leaf : leaf + "." + extension;
  return [...clean.split("/").slice(0, -1), safeLeaf].join("/");
}
export function validateDocumentContent(format: JdDocumentFormat, content: string): string {
  if (typeof content !== "string" || content.trim().length < 20 || new TextEncoder().encode(content).length > 95000) {
    throw new Error("Document content must be between 20 bytes and 95 KB");
  }
  if (format === "json") {
    const parsed = JSON.parse(content);
    return JSON.stringify(parsed, null, 2);
  }
  if (format === "xlsx") {
    const spec = JSON.parse(content);
    if (!Array.isArray(spec.sheets) || spec.sheets.length < 1 || spec.sheets.length > 8) {
      throw new Error("An XLSX draft needs between 1 and 8 sheets");
    }
    for (const sheet of spec.sheets) {
      if (!Array.isArray(sheet.rows) || sheet.rows.length < 1 || sheet.rows.length > 500) {
        throw new Error("Each spreadsheet sheet needs between 1 and 500 rows");
      }
      if (sheet.rows.some((row: unknown) => !Array.isArray(row) || row.length > 30 ||
        row.some((cell: unknown) => !["string", "number", "boolean"].includes(typeof cell)))) {
        throw new Error("Spreadsheet cells must be strings, numbers or booleans, with at most 30 columns");
      }
    }
  }
  if (format === "pptx") {
    const spec = JSON.parse(content);
    if (!Array.isArray(spec.slides) || spec.slides.length < 1 || spec.slides.length > 20) {
      throw new Error("A presentation needs between 1 and 20 slides");
    }
    for (const slide of spec.slides) {
      if (typeof slide.title !== "string" || !Array.isArray(slide.bullets) || slide.bullets.length > 8 ||
        slide.bullets.some((bullet: unknown) => typeof bullet !== "string")) {
        throw new Error("Each presentation slide needs a title and up to 8 text bullets");
      }
    }
  }
  return content;
}

export async function generateJdDocument(format: JdDocumentFormat, rawContent: string, title: string): Promise<{
  bytes: Uint8Array;
  mimeType: string;
  extension: string;
  textContent: string;
}> {
  const content = validateDocumentContent(format, rawContent);
  if (["txt", "md", "csv", "json", "html", "css", "js", "ts", "py", "sql", "xml", "yaml"].includes(format)) {
    return { bytes: new TextEncoder().encode(content), mimeType: JD_DOCUMENT_MIME[format], extension: format, textContent: content };
  }

  if (format === "xlsx") {
    const XLSX = await import("https://esm.sh/xlsx@0.18.5");
    const spec = JSON.parse(content);
    const workbook = XLSX.utils.book_new();
    for (const sheet of spec.sheets) {
      const rows = sheet.rows.map((row: unknown[]) => row.map((cell) => cell));
      const worksheet = XLSX.utils.aoa_to_sheet(rows);
      XLSX.utils.book_append_sheet(workbook, worksheet, String(sheet.name || "Sheet").slice(0, 31));
    }
    const bytes = new Uint8Array(XLSX.write(workbook, { type: "array", bookType: "xlsx" }));
    return { bytes, mimeType: JD_DOCUMENT_MIME.xlsx, extension: "xlsx", textContent: content };
  }

  if (format === "pptx") {
    const module = await import("https://esm.sh/pptxgenjs@3.12.0");
    const PptxGenJS = module.default;
    const presentation = new PptxGenJS();
    presentation.layout = "LAYOUT_WIDE";
    const spec = JSON.parse(content);
    for (const item of spec.slides) {
      const slide = presentation.addSlide();
      slide.background = { color: "FFFFFF" };
      slide.addText(String(item.title).slice(0, 180), { x: 0.55, y: 0.35, w: 12.1, h: 0.75, fontSize: 26, bold: true, color: "20242B", breakLine: false });
      const bullets = item.bullets.map((bullet: string) => ({ text: bullet.slice(0, 500), options: { bullet: { indent: 18 }, hanging: 4 } }));
      slide.addText(bullets, { x: 0.7, y: 1.35, w: 11.8, h: 5.5, fontSize: 17, color: "333942", breakLine: false, valign: "top", paraSpaceAfter: 12 });
    }
    const output = await presentation.write({ outputType: "uint8array" });
    return { bytes: new Uint8Array(output as Uint8Array), mimeType: JD_DOCUMENT_MIME.pptx, extension: "pptx", textContent: content };
  }

  const module = await import("https://esm.sh/docx@8.5.0");
  const children: any[] = [];
  children.push(new module.Paragraph({ text: title, heading: module.HeadingLevel.TITLE }));
  const lines = content.split(/\r?\n/).slice(0, 500);
  for (const line of lines) {
    if (!line.trim()) continue;
    const heading = line.match(/^(#{1,3})\s+(.+)$/);
    if (heading) {
      const level = heading[1].length === 1 ? module.HeadingLevel.HEADING_1
        : heading[1].length === 2 ? module.HeadingLevel.HEADING_2 : module.HeadingLevel.HEADING_3;
      children.push(new module.Paragraph({ text: heading[2].slice(0, 500), heading: level }));
    } else {
      children.push(new module.Paragraph({ children: [new module.TextRun(line.slice(0, 3000))] }));
    }
  }
  const document = new module.Document({ sections: [{ children }] });
  const output = await module.Packer.toBuffer(document);
  const bytes = new Uint8Array(output);
  return { bytes, mimeType: JD_DOCUMENT_MIME.docx, extension: "docx", textContent: content };
}

/** Conservative success check for agent tool results. Non-empty objects alone do not prove success. */
export function isSuccessfulToolResult(value: unknown): value is Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const result = value as Record<string, unknown>;
  if (Object.keys(result).length === 0) return false;
  if (result.ok === false || result.success === false || result.outcome === "unknown") return false;
  if (typeof result.status === "string" && ["outcome_unknown", "unknown"].includes(result.status.toLowerCase())) return false;
  if (typeof result.error === "string" && result.error.trim()) return false;
  if (typeof result.status === "string" && ["failed", "failure", "error", "rejected", "cancelled"].includes(result.status.toLowerCase())) return false;
  return true;
}

/** Identify a tool result that explicitly says its side effect may have happened without verification. */
export function isUnknownToolResult(value: unknown): boolean {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const result = value as Record<string, unknown>;
  if (result.outcome === "unknown" || result.status === "outcome_unknown" || result.status === "unknown") return true;
  return isUnknownToolResult(result.result) || isUnknownToolResult(result.structuredContent);
}

/** Only explicit provider/tool rejection is a confirmed failure; missing evidence is ambiguous. */
export function isExplicitToolFailure(value: unknown): boolean {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const result = value as Record<string, unknown>;
  if (result.ok === false || result.success === false) return true;
  if (typeof result.error === "string" && result.error.trim()) return true;
  if (typeof result.status === "string" && ["failed", "failure", "error", "rejected", "cancelled"].includes(result.status.toLowerCase())) return true;
  return isExplicitToolFailure(result.result) || isExplicitToolFailure(result.structuredContent);
}

import { z } from "npm:zod@^4.3.6";

const asObject = (value: unknown): Record<string, unknown> =>
  value && typeof value === "object" && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};

/** Convert the JSON Schema subset emitted by JD's native tool registry into
 * Zod schemas so MCP clients receive the real argument contract. */
export function jsonSchemaToZod(input: unknown): any {
  const schema = asObject(input);
  if (Array.isArray(schema.anyOf)) {
    const options = schema.anyOf.map(jsonSchemaToZod);
    if (options.length === 1) return options[0];
    return z.union(options as [any, any, ...any[]]);
  }
  if (Array.isArray(schema.oneOf)) {
    const options = schema.oneOf.map(jsonSchemaToZod);
    if (options.length === 1) return options[0];
    return z.union(options as [any, any, ...any[]]);
  }
  if (Array.isArray(schema.type)) {
    const options = (schema.type as unknown[]).map((type) => jsonSchemaToZod({ ...schema, type }));
    if (options.length === 1) return options[0];
    return z.union(options as [any, any, ...any[]]);
  }
  if (Array.isArray(schema.enum) && schema.enum.length > 0) {
    const values = schema.enum.filter((value): value is string => typeof value === "string");
    if (values.length > 0) return z.enum(values as [string, ...string[]]);
  }
  if ("const" in schema) return z.literal(schema.const as any);

  let result: any;
  switch (schema.type) {
    case "object": {
      const properties = asObject(schema.properties);
      const required = new Set(Array.isArray(schema.required) ? schema.required.filter((v): v is string => typeof v === "string") : []);
      const shape: Record<string, any> = {};
      for (const [key, value] of Object.entries(properties)) {
        const property = jsonSchemaToZod(value);
        shape[key] = required.has(key) ? property : property.optional();
      }
      result = z.object(shape);
      if (schema.additionalProperties === false) result = result.strict();
      else if (schema.additionalProperties && typeof schema.additionalProperties === "object") {
        result = result.catchall(jsonSchemaToZod(schema.additionalProperties));
      }
      break;
    }
    case "array": {
      result = z.array(jsonSchemaToZod(schema.items || {}));
      if (typeof schema.minItems === "number") result = result.min(schema.minItems);
      if (typeof schema.maxItems === "number") result = result.max(schema.maxItems);
      break;
    }
    case "string": {
      result = z.string();
      if (typeof schema.minLength === "number") result = result.min(schema.minLength);
      if (typeof schema.maxLength === "number") result = result.max(schema.maxLength);
      break;
    }
    case "integer":
    case "number": {
      result = z.number();
      if (schema.type === "integer") result = result.int();
      if (typeof schema.minimum === "number") result = result.min(schema.minimum);
      if (typeof schema.maximum === "number") result = result.max(schema.maximum);
      break;
    }
    case "boolean": result = z.boolean(); break;
    case "null": result = z.null(); break;
    default: result = z.unknown();
  }
  if (schema.nullable === true && schema.type !== "null") result = result.nullable();
  if ("default" in schema) result = result.default(schema.default);
  return result;
}

import {decryptSecret,encryptSecret,importAesKey} from './jd-oauth-crypto.ts';
import {getJdSecret} from './jd-secrets.ts';
import {WORKSPACE_PROVIDERS} from './jd-workspace-connectors.mjs';
import {oauthJson,tokenBundle,tokenRequest} from './jd-connector-oauth-policy.mjs';
export async function refreshWorkspaceConnection(ctx:any,providerId:string,dependencies:any={}){
 if(!['owner','admin','manager'].includes(ctx.role)||!Object.hasOwn(WORKSPACE_PROVIDERS,providerId))throw Error('Workspace refresh is not authorised.');
 const {data:row,error}=await ctx.admin.from('jd_business_oauth_connections').select('provider_id,status,scopes,connected_by,enabled_read_services,token_expires_at,encrypted_credentials').eq('school_id',ctx.schoolId).eq('provider_id',providerId).eq('connected_by',ctx.userId).maybeSingle();
 if(error||row?.status!=='connected'||row.connected_by!==ctx.userId||!row.encrypted_credentials)throw Error('No active personal connection to refresh.');
 const key=await importAesKey(dependencies.key||getJdSecret('JD_OAUTH_ENCRYPTION_KEY'));
 const stored=JSON.parse(await decryptSecret(row.encrypted_credentials,key));if(!stored.refresh_token)throw Error('Provider did not issue offline access. Sign in again.');
 const env=dependencies.env||((k:string)=>Deno.env.get(k));
 const provider=WORKSPACE_PROVIDERS[providerId as keyof typeof WORKSPACE_PROVIDERS],client=env(provider.clientIdEnv),secret=env(provider.clientSecretEnv);
 if(!client||!secret)throw Error('Operator provider configuration is missing.');
 const {error:auditError}=await ctx.admin.rpc('jd_business_audit',{p_school_id:ctx.schoolId,p_actor_id:ctx.userId,p_event_type:'workspace.oauth.refresh_requested',p_event:{provider_id:providerId}});
 if(auditError)throw Error('Could not record refresh audit.');
 const lease=crypto.randomUUID(),base={p_school:ctx.schoolId,p_actor:ctx.userId,p_provider:providerId,p_previous:row.encrypted_credentials,p_lease:lease};
 const {data:claimed,error:claimError}=await ctx.admin.rpc('jd_claim_workspace_refresh',base);
 if(claimError||claimed!==true)throw Error('Connection is refreshing or changed. Try again shortly.');
 try{
  const config={client_id:client,client_secret:secret,token_endpoint_auth_method:'client_secret_post'};
  const endpoint=providerId==='google-workspace'?'https://oauth2.googleapis.com/token':'https://login.microsoftonline.com/common/oauth2/v2.0/token';
  const payload=await oauthJson(await (dependencies.fetch||fetch)(endpoint,tokenRequest(config,{grant_type:'refresh_token',refresh_token:stored.refresh_token})));
  const bundle=tokenBundle(payload,{...stored,scope:(row.scopes||[]).join(' ')},dependencies.now??Date.now());
  if(!bundle.expires_at)throw Error('Missing provider expiry.');
  const scopes=bundle.scope.split(/[ ,]+/).filter(Boolean),encrypted=await encryptSecret(JSON.stringify(bundle),key);
  const {data:saved,error:saveError}=await ctx.admin.rpc('jd_save_workspace_refresh',{...base,p_bundle:encrypted,p_expiry:bundle.expires_at,p_scopes:scopes});
  if(saveError||saved!==true)throw Error('Connection changed during refresh.');
  return {...row,encrypted_credentials:encrypted,token_expires_at:bundle.expires_at,scopes};
